<?php
declare(strict_types=1);
$app=require dirname(__DIR__,3).'/bootstrap.php';$user=$app['auth']->requireRole(['ADMIN']);if($_SERVER['REQUEST_METHOD']!=='POST'||!$app['csrf']->verify($_POST['_csrf']??null)){http_response_code(400);exit('Invalid request.');}
try{$id=(int)($_POST['invoice_id']??0);$q=$app['pdo']->prepare('SELECT i.id,i.invoice_number,i.business_id,a.EMAIL,(SELECT TOP(1) u.email FROM dbo.business_user_links l JOIN dbo.app_users u ON u.id=l.user_id WHERE l.business_id=i.business_id AND l.ended_at IS NULL AND u.is_active=1 ORDER BY l.assigned_at) user_email FROM dbo.business_invoices i JOIN dbo.ARBK_LIST a ON a.REGULATION_ID=i.business_id WHERE i.id=:id');$q->execute(['id'=>$id]);$invoice=$q->fetch();if(!$invoice)throw new DomainException('Fatura nuk u gjet.');$email=trim((string)($_POST['email']??''))?:((string)($invoice['user_email']??'')?:trim((string)($invoice['EMAIL']??'')));if(filter_var($email,FILTER_VALIDATE_EMAIL)===false)throw new DomainException('Biznesi nuk ka email valid.');(new App\Service\TrackedMessageService($app['pdo'],$app['config'],new App\Service\GraphMailer($app['config'])))->send('INVOICE',$email,'Fatura '.$invoice['invoice_number'],'Fatura juaj është gati për shkarkim.','DOWNLOAD_INVOICE','/portal/invoice-pdf.php?id='.$id,'Shkarko faturën',(int)$user['id'],'INVOICE',$id);$app['pdo']->prepare('UPDATE dbo.business_invoices SET emailed_at=SYSUTCDATETIME() WHERE id=:id')->execute(['id'=>$id]);flash('success','Fatura u dërgua me email.');}
catch(DomainException $e){flash('error',$e->getMessage());}catch(Throwable $e){error_log($e->__toString());flash('error','Fatura nuk mund të dërgohej.');}redirect('/admin/finance/index.php');
